/* ------------------------------------------------------------------ */
/* Backlight — LEDC PWM, gamma-corrected                                */
/* ------------------------------------------------------------------ */

#define LEDC_TIMER      LEDC_TIMER_0
#define LEDC_CHANNEL    LEDC_CHANNEL_0
#define LEDC_DUTY_MAX   ((1u << LEDC_TIMER_13_BIT) - 1u)

static bool s_backlight_ready;

/* Perceptual curve: L = (x/100)^2.2, so 20% looks like 20% and not "nearly
 * off". Without this the first third of the range is visually indistinguishable. */
static uint32_t gamma_duty(uint8_t percent)
{
    if (percent > 100u) {
        percent = 100u;
    }
    /* Fixed-point gamma on [0,1] in 16.16. Integer power via repeated squaring
     * keeps this free of floating point and of any libm dependency. */
    if (percent == 0u) {
        return 0u;
    }
    if (percent == 100u) {
        return LEDC_DUTY_MAX;
    }
    /* x^2.2 approximated by x^2 * x^0.2; the 0.2 term is close enough to a
     * linear blend for a backlight. */
    uint32_t x = (uint32_t)percent;                       /* 0..100 */
    uint32_t sq = (x * x) / 100u;                         /* 0..100  */
    uint32_t frac = (x * 20u) / 100u;                     /* 0..20   */
    uint32_t y = sq + ((100u - sq) * frac) / 100u;        /* 0..100  */
    return (y * LEDC_DUTY_MAX) / 100u;
}

static esp_err_t backlight_init(void)
{
    const int gpio = FRAME_DISPLAY_BACKLIGHT_GPIO;
    if (gpio < 0) {
        ESP_LOGW(TAG, "board declares no backlight GPIO");
        return ESP_OK;
    }

    const ledc_timer_config_t timer = {
        .speed_mode      = LEDC_LOW_SPEED_MODE,
        .duty_resolution = LEDC_TIMER_13_BIT,
        .timer_num       = LEDC_TIMER,
        .freq_hz         = FRAME_DISPLAY_BACKLIGHT_FREQ_HZ,
        .clk_cfg         = LEDC_AUTO_CLK,
    };
    ESP_RETURN_ON_ERROR(ledc_timer_config(&timer), TAG, "ledc timer");

    const ledc_channel_config_t ch = {
        .gpio_num   = gpio,
        .speed_mode = LEDC_LOW_SPEED_MODE,
        .channel    = LEDC_CHANNEL,
        .timer_sel  = LEDC_TIMER,
        .duty       = 0,
        .hpoint     = 0,
    };
    ESP_RETURN_ON_ERROR(ledc_channel_config(&ch), TAG, "ledc channel");

    s_backlight_ready = true;
    board_backlight_set(FRAME_DISPLAY_BACKLIGHT_DEFAULT_PCT);
    return ESP_OK;
}

static void board_backlight_set(uint8_t percent)
{
    if (!s_backlight_ready) {
        return;
    }
    uint32_t duty = gamma_duty(percent);
    /* Polarity is a property of the driver transistor, not of the panel. */
    if (!FRAME_DISPLAY_BACKLIGHT_ACTIVE_HIGH) {
        duty = LEDC_DUTY_MAX - duty;
    }
    ledc_set_duty(LEDC_LOW_SPEED_MODE, LEDC_CHANNEL, duty);
    ledc_update_duty(LEDC_LOW_SPEED_MODE, LEDC_CHANNEL);
}

/* ------------------------------------------------------------------ */
/* Bring-up                                                             */
/* ------------------------------------------------------------------ */

static esp_err_t board_init(void)
{
    /* The RGB data bus is driven by the LCD_CAM peripheral through its GPIO
     * matrix, so no explicit gpio_config is needed for those pins. */

    esp_err_t err = backlight_init();
    if (err != ESP_OK) {
        /* A missing backlight is not fatal: the panel may still be visible. */
        ESP_LOGW(TAG, "backlight init failed: %s", esp_err_to_name(err));
    }

    ESP_LOGI(TAG, "board %s rev %s: %ux%u @ %u Hz, profile %d",
             FRAME_BOARD_ID, FRAME_BOARD_REVISION,
             (unsigned)FRAME_DISPLAY_WIDTH, (unsigned)FRAME_DISPLAY_HEIGHT,
             (unsigned)FRAME_DISPLAY_REFRESH_HZ, (int)FRAME_DISPLAY_PROFILE);
    return ESP_OK;
}

static void board_enter_sleep(void)
{
    /* Dumb RGB panels scan continuously; there is no GRAM to put to sleep.
     * The realistic saving is backlight plus refresh throttling. */
    board_backlight_set(0);
}

static void board_exit_sleep(void)
{
    board_backlight_set(FRAME_DISPLAY_BACKLIGHT_DEFAULT_PCT);
}
